:root{
  --burgundy:#2B0813; --burgundy-2:#3d0f1e; --gold:#D4AF37; --gold-soft:#E6C280; --ivory:#FDFBF7;
  --serif:'Cormorant Garamond',Georgia,serif; --sans:'Cairo',system-ui,sans-serif;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scroll-padding-top:72px}
body{font-family:var(--sans);background:var(--burgundy);color:var(--ivory);line-height:1.7;-webkit-font-smoothing:antialiased}
a{color:inherit}
:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
h1,h2,h3,.logo{font-family:var(--serif);font-weight:600;line-height:1.15}

/* Header */
.site-header{position:fixed;inset:0 0 auto 0;z-index:50;display:flex;align-items:center;justify-content:space-between;padding:14px 20px;transition:background .3s}
.site-header.scrolled{background:rgba(43,8,19,.94);backdrop-filter:blur(10px);box-shadow:0 1px 0 rgba(212,175,55,.25)}
.logo{font-size:1.6rem;color:var(--gold);text-decoration:none;letter-spacing:.02em}
.menu-btn{background:none;border:0;width:40px;height:40px;display:grid;align-content:center;gap:7px;cursor:pointer}
.menu-btn span{display:block;height:2px;background:var(--gold);transition:transform .25s}
.menu-btn[aria-expanded="true"] span:first-child{transform:translateY(4.5px) rotate(45deg)}
.menu-btn[aria-expanded="true"] span:last-child{transform:translateY(-4.5px) rotate(-45deg)}
.nav{position:fixed;inset:60px 0 auto 0;background:var(--burgundy);display:none;flex-direction:column;gap:6px;padding:20px;border-top:1px solid rgba(212,175,55,.25)}
.nav.open{display:flex}
.nav a{text-decoration:none;padding:10px 0}
.nav a:not(.btn):hover{color:var(--gold)}

/* Buttons */
.btn{display:inline-block;border-radius:2px;padding:14px 28px;font:600 1rem var(--sans);text-decoration:none;text-align:center;cursor:pointer;border:1px solid var(--gold);transition:box-shadow .3s,background .3s}
.btn-gold{background:linear-gradient(135deg,var(--gold),var(--gold-soft));color:var(--burgundy)}
.btn-gold:hover{box-shadow:0 0 22px rgba(212,175,55,.65)}
.btn-sm{padding:10px 18px}

/* Hero */
.hero{position:relative;min-height:100svh;display:grid;place-items:center;overflow:hidden;text-align:center}
.hero-bg{position:absolute;inset:-10% 0;background:
  linear-gradient(180deg,rgba(43,8,19,.55),rgba(43,8,19,.9)),
  var(--hero-img,none),
  radial-gradient(circle at 50% 30%,#6b1a34 0%,var(--burgundy) 70%);
  background-size:cover;background-position:center;will-change:transform}
.hero-inner{position:relative;padding:110px 22px 60px;max-width:820px}
.hero h1{font-size:clamp(2.4rem,9vw,4.6rem);color:var(--ivory);margin-bottom:14px}
.hero .ar{font-size:1.25rem;color:var(--gold-soft);margin-bottom:18px}
.hero .sub{max-width:560px;margin:0 auto 30px;opacity:.88}

/* Sections */
.section{padding:84px 22px;max-width:1100px;margin:0 auto}
.alt{max-width:none;background:var(--burgundy-2)}
.alt>*{max-width:1100px;margin-inline:auto}
.section h2{font-size:clamp(2rem,6vw,3rem);color:var(--gold);margin-bottom:12px}
.lead{max-width:60ch;margin-bottom:34px;opacity:.9}
.grid{display:grid;gap:16px}
.card{padding:26px;border:1px solid rgba(212,175,55,.3);background:rgba(255,255,255,.05);backdrop-filter:blur(8px);border-radius:14px}
.card h3{font-size:1.5rem;color:var(--gold-soft);margin-bottom:8px}
blockquote.card cite{display:block;margin-top:10px;color:var(--gold-soft);font-style:normal}

/* Portfolio */
.filters{display:flex;flex-wrap:wrap;gap:8px;margin:20px auto 26px}
.chip{background:none;color:var(--ivory);border:1px solid rgba(212,175,55,.45);padding:8px 16px;border-radius:30px;font:inherit;cursor:pointer;transition:background .2s}
.chip.active,.chip:hover{background:var(--gold);color:var(--burgundy)}
.gallery{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}
.tile{position:relative;aspect-ratio:4/5;border:0;border-radius:6px;overflow:hidden;cursor:pointer;color:var(--ivory);
  background:var(--img),linear-gradient(160deg,#6b1a34,var(--burgundy));background-size:cover;background-position:center}
.tile span{position:absolute;inset:auto 0 0;padding:26px 12px 12px;text-align:left;font-size:.9rem;background:linear-gradient(transparent,rgba(43,8,19,.92))}
.tile.hide{display:none}

/* Planner */
.planner{display:grid;gap:18px;max-width:520px}
.planner label,.planner legend{display:block;font-weight:600}
.planner select,.planner input[type=number]{width:100%;margin-top:6px;padding:12px;background:rgba(255,255,255,.07);color:var(--ivory);border:1px solid rgba(212,175,55,.4);border-radius:4px;font:inherit}
.planner option{color:#222}
fieldset{border:1px solid rgba(212,175,55,.3);padding:14px;border-radius:6px}
.check{font-weight:400!important;padding:5px 0}
.check input{accent-color:var(--gold);margin-inline-end:8px}

/* Stats */
.stats{display:grid;gap:22px;margin-bottom:34px}
.stats div{border-inline-start:2px solid var(--gold);padding-inline-start:16px}
.stats strong{display:block;font:600 3rem/1 var(--serif);color:var(--gold)}

/* Footer */
.site-footer{text-align:center;padding:50px 22px;border-top:1px solid rgba(212,175,55,.25)}
.site-footer p{margin-top:8px}
.small{font-size:.85rem;opacity:.7}

/* Lightbox */
.lightbox{position:fixed;inset:0;z-index:100;background:rgba(20,3,9,.96);display:grid;place-items:center;align-content:center;gap:10px;padding:20px;text-align:center}
.lightbox[hidden]{display:none}
.lb-img{width:min(92vw,820px);aspect-ratio:4/3;border-radius:8px;background-size:cover;background-position:center;background-color:var(--burgundy-2)}
.lb-note{color:var(--gold-soft)}
.lb-close{position:absolute;top:14px;right:18px;background:none;border:0;color:var(--gold);font-size:2.4rem;cursor:pointer}

/* Reveal: one soft entrance for cards */
.reveal{opacity:0;transform:translateY(18px);transition:opacity .7s,transform .7s}
.reveal.in{opacity:1;transform:none}

@media(min-width:760px){
  .menu-btn{display:none}
  .nav{position:static;display:flex;flex-direction:row;align-items:center;gap:26px;padding:0;border:0;background:none}
  .site-header{padding:18px 48px}
  .grid{grid-template-columns:repeat(3,1fr)}
  .gallery{grid-template-columns:repeat(3,1fr);gap:14px}
  .stats{grid-template-columns:repeat(3,1fr)}
}
@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  .reveal{opacity:1;transform:none;transition:none}
}

/* ===== Embedded photos (replace any url(...) with your own image path to swap a photo) ===== */
:root{
  --p-gold:url("data:image/jpeg;base64,");
  --p-ceiling:url("data:image/jpeg;base64,");
  --p-arches:url("data:image/jpeg;base64,");
  --p-entrance:url("data:image/jpeg;base64,");
  --p-canopy:url("data:image/jpeg;base64,");
  --p-crystal:url("data:image/jpeg;base64,");
  --hero-img:var(--p-gold);
}